S.lula_cop.velha = true; S.lula_cop.velhaMotivo = 'COP31: a cobertura de 12/11 está em lula_delcy_antalia; segue acessível pelo link compartilhado';

/* ===== 18h: regionais com até 2 dias voltam às regiões (cada região exige 5 matérias) ===== */
